#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L, C;
    if (!(cin >> L >> C)) return 0;

    const int MAXV = 26 * 26;
    vector<vector<int>> rowCoeff(L, vector<int>(MAXV, 0));
    vector<vector<int>> colCoeff(C, vector<int>(MAXV, 0));
    vector<long long> rowSum(L);
    vector<long long> colSum(C);
    vector<bool> seen(MAXV, false);
    int totalVars = 0;

    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < C; ++j) {
            string name;
            cin >> name;
            int id = (name[0] - 'a') * 26 + (name[1] - 'a');
            if (!seen[id]) {
                seen[id] = true;
                ++totalVars;
            }
            rowCoeff[i][id]++;
            colCoeff[j][id]++;
        }
        long long S;
        cin >> S;
        rowSum[i] = S;
    }

    for (int j = 0; j < C; ++j) {
        cin >> colSum[j];
    }

    vector<int> rowUnknown(L, 0), colUnknown(C, 0);
    for (int i = 0; i < L; ++i) {
        for (int id = 0; id < MAXV; ++id) {
            if (rowCoeff[i][id] > 0) rowUnknown[i]++;
        }
    }
    for (int j = 0; j < C; ++j) {
        for (int id = 0; id < MAXV; ++id) {
            if (colCoeff[j][id] > 0) colUnknown[j]++;
        }
    }

    vector<bool> known(MAXV, false);
    vector<long long> val(MAXV, 0);
    int solved = 0;

    while (solved < totalVars) {
        bool found = false;

        for (int i = 0; i < L && !found; ++i) {
            if (rowUnknown[i] == 1) {
                int var = -1;
                for (int id = 0; id < MAXV; ++id) {
                    if (rowCoeff[i][id] > 0 && !known[id]) {
                        var = id;
                        break;
                    }
                }
                if (var != -1) {
                    long long value = rowSum[i] / rowCoeff[i][var];
                    known[var] = true;
                    val[var] = value;
                    ++solved;

                    for (int r = 0; r < L; ++r) {
                        if (rowCoeff[r][var] > 0) {
                            rowSum[r] -= rowCoeff[r][var] * value;
                            rowUnknown[r]--;
                        }
                    }
                    for (int c = 0; c < C; ++c) {
                        if (colCoeff[c][var] > 0) {
                            colSum[c] -= colCoeff[c][var] * value;
                            colUnknown[c]--;
                        }
                    }
                    found = true;
                }
            }
        }

        if (found) continue;

        for (int j = 0; j < C && !found; ++j) {
            if (colUnknown[j] == 1) {
                int var = -1;
                for (int id = 0; id < MAXV; ++id) {
                    if (colCoeff[j][id] > 0 && !known[id]) {
                        var = id;
                        break;
                    }
                }
                if (var != -1) {
                    long long value = colSum[j] / colCoeff[j][var];
                    known[var] = true;
                    val[var] = value;
                    ++solved;

                    for (int r = 0; r < L; ++r) {
                        if (rowCoeff[r][var] > 0) {
                            rowSum[r] -= rowCoeff[r][var] * value;
                            rowUnknown[r]--;
                        }
                    }
                    for (int c = 0; c < C; ++c) {
                        if (colCoeff[c][var] > 0) {
                            colSum[c] -= colCoeff[c][var] * value;
                            colUnknown[c]--;
                        }
                    }
                    found = true;
                }
            }
        }

        if (!found) break;
    }

    for (int id = 0; id < MAXV; ++id) {
        if (seen[id]) {
            char c1 = 'a' + (id / 26);
            char c2 = 'a' + (id % 26);
            cout << c1 << c2 << ' ' << val[id] << '\n';
        }
    }

    return 0;
}
